using S=std::string; using V=std::vector<S>; using U=uint64_t;
S quote(const S&s){S t="\"";for(unsigned char c:s){if(c=='"'||c=='\\'){t+='\\';t+=c;}else if(c=='\n')t+="\\n";else if(c=='\r')t+="\\r";else if(c=='\t')t+="\\t";else if(c<32){char b[8];snprintf(b,8,"\\u%04x",c);t+=b;}else t+=c;}return t+'"';}
